import {CASE_FIELDS,reconstructionMarkup} from './case-reconstruction.js?v=46';
import {DEDUCTIONS,toggleClueSelection} from './clue-synthesis.js?v=46';
import {mountBookmarks} from './arg-bookmarks.js?v=46';
import {bindNotebookFeedback} from './ui-interactions.js?v=46';
import {hintsFor} from './arg-hints.js?v=46';
import {EVIDENCE,AUDIT_EDGES} from './arg-content.js?v=46';
import {owned,truth,truthy,siteURL,escapeHTML as esc} from './arg-engine.js?v=46';
export function mountPinboard(store,{site}){
 let selected=[],caseDraft=null,draft='',returnFocus=null,hintDepth=-1,hintContext='';const shell=document.createElement('div');shell.className='arg-pocket';shell.innerHTML='<button type="button" class="arg-pocket-toggle" aria-controls="argNotebook" aria-expanded="false">▤ 随身调查本 <b data-pocket-count>0</b><span class="arg-unread-dot" aria-hidden="true"></span></button><dialog id="argNotebook" class="arg-notebook" aria-labelledby="argNotebookTitle"><header><div><small>高三 / 随堂记录</small><h2 id="argNotebookTitle">by的错题本</h2></div><button type="button" data-pocket-close aria-label="合上调查本">×</button></header><details class="arg-bookmarks"></details><div class="arg-notebook-body"></div></dialog><div class="arg-small-toast" role="status" aria-live="polite"></div>';document.body.append(shell);const dialog=shell.querySelector('dialog'),body=shell.querySelector('.arg-notebook-body'),toggle=shell.querySelector('.arg-pocket-toggle'),toastNode=shell.querySelector('.arg-small-toast');let timer,hadVault=!!store.get().vault;
 function feedback(message){clearTimeout(timer);toastNode.textContent=message;toastNode.classList.add('show');timer=setTimeout(()=>toastNode.classList.remove('show'),2800);}
 function sound(){if(!truthy(store.get(),'prefs','sound'))return;try{const Audio=window.AudioContext||window.webkitAudioContext;if(!Audio)return;const a=new Audio(),o=a.createOscillator(),g=a.createGain();o.frequency.value=520;g.gain.setValueAtTime(.035,a.currentTime);g.gain.exponentialRampToValueAtTime(.001,a.currentTime+.12);o.connect(g);g.connect(a.destination);o.start();o.stop(a.currentTime+.13);o.onended=()=>a.close().catch(()=>{});}catch{}}
 function draw(){const s=store.get(),hints=hintsFor(s);if(hintContext!==hints[0]){hintContext=hints[0];hintDepth=-1;}const ids=Object.keys(EVIDENCE).filter(id=>owned(s,id));shell.querySelector('[data-pocket-count]').textContent=ids.length;if(!dialog.open)return;const input=body.querySelector('textarea');if(input)draft=input.value;else draft=s.notes.personal?.value||'';const focus=body.contains(document.activeElement)?document.activeElement.name:null;
  body.innerHTML=`<p class="arg-pen">先对材料，再认人。<span>${truth(s).links}/5 组核心关系已核实</span></p><div class="arg-card-grid">${ids.map(id=>`<label class="arg-evidence-card ${selected.includes(id)?'selected':''}"><input type="checkbox" data-card="${esc(id)}" aria-label="选择${esc(EVIDENCE[id].title)}" ${selected.includes(id)?'checked':''}><small>${esc(EVIDENCE[id].code||'材料')}</small><strong>${esc(EVIDENCE[id].title)}</strong><span>${esc(EVIDENCE[id].text||'')}</span></label><a class="arg-card-source" href="${siteURL(EVIDENCE[id].site,EVIDENCE[id].params,site)}">翻原件 ↗</a>`).join('')||'<p>看到可疑字段可以直接点击；关键附件阅读片刻也会自动记入。</p>'}</div><section class="arg-synthesis"><h3>串联疑点</h3><p>${selected.length?selected.map(id=>esc(EVIDENCE[id].title)).join(' ＋ '):'勾选两份已收录材料，放在一起想一想。'}</p><form data-pocket-synthesize><button ${selected.length===2?'':'disabled'}>交叉比对</button></form><p data-synthesis-result role="status" aria-live="polite"></p><div class="arg-deductions">${DEDUCTIONS.filter(d=>truthy(s,'deductions',d.id)).map(d=>`<article data-deduction="${d.id}"><small>核心推论 / by</small><h4>${esc(d.title)}</h4><p>${esc(d.text)}</p></article>`).join('')}</div></section><section class="arg-link-work"><h3>把两份材料放在一起</h3><p>${selected.length?selected.map(id=>esc(EVIDENCE[id].title)).join(' → '):'点选两张卡片，再提出关系。'}</p><form data-pocket-link><label>关系<select name="relation"><option value="contradicts">互相矛盾</option><option value="amends">被改写为（有方向）</option><option value="settles">被用于结算（有方向）</option></select></label><button>提出质疑</button><button type="button" data-pocket-clear>清空选择</button></form><p data-pocket-result role="status"></p><svg class="arg-mini-wires" viewBox="0 0 320 70" aria-hidden="true">${AUDIT_EDGES.filter(e=>truthy(s,'links',e.key)).map((e,i)=>`<path d="M8 ${10+i*12} Q160 ${5+i*8} 312 ${10+i*12}"/>`).join('')}</svg><ul>${AUDIT_EDGES.filter(e=>truthy(s,'links',e.key)).map(e=>`<li>${esc(e.label)} <button type="button" data-unlink="${esc(e.key)}">重核</button></li>`).join('')}</ul></section><form data-pocket-note><label>随手记<textarea name="personal" maxlength="4000" rows="4">${esc(draft)}</textarea></label><button>保存手记</button></form><section class="arg-pocket-hints">${hintDepth>=0?hints.slice(0,hintDepth+1).map((line,i)=>`<details ${i===hintDepth?'open':''}><summary>${['一级：疑点材料','二级：核对关系','三级：具体建议'][i]}</summary><p>${esc(line)}</p></details>`).join(''):''}${hintDepth<2?`<button type="button" data-hint-more>${hintDepth<0?'想不动时翻一下':'展开下一级提示'}</button>`:''}</section><label class="arg-sound"><input type="checkbox" data-pocket-sound ${truthy(s,'prefs','sound')?'checked':''}> 轻提示音（默认关闭）</label>${truth(s).first?`<a class="arg-note-return" href="${siteURL('pan',{folder:'notice'},site)}">查看通报与处理意见 →</a>`:''}${!store.available()?'<p class="arg-storage-warning">浏览器存储当前不可用，跨页进度可能无法保存。</p>':''}${reconstructionMarkup(s,esc,{draft:caseDraft})}<footer class="arg-notebook-meta">《第三份阳性报告》 · v3.2<br>虚构校园故事；人物、文书与站点均为创作内容，不作为现实检验或诊疗凭证。</footer>`;if(focus)body.querySelector(`[name="${focus}"]`)?.focus({preventScroll:true});
 }
 function close(){if(body.querySelector('textarea')){draft=body.querySelector('textarea').value;store.dispatch('note',{text:draft});}dialog.close();toggle.setAttribute('aria-expanded','false');returnFocus?.focus?.({preventScroll:true});}
 mountBookmarks(store,{container:shell.querySelector('.arg-bookmarks'),site,navigate:href=>{close();location.assign(href);}});
 const notebookFeedback=bindNotebookFeedback({dialog,toggle,close});
 toggle.addEventListener('click',()=>{notebookFeedback.acknowledge();returnFocus=document.activeElement;dialog.showModal();toggle.setAttribute('aria-expanded','true');draw();});shell.querySelector('[data-pocket-close]').addEventListener('click',close);dialog.addEventListener('cancel',e=>{e.preventDefault();close();});
 shell.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.hasAttribute('data-hint-more')){hintDepth=Math.min(2,hintDepth+1);draw();return;}if(b.hasAttribute('data-pocket-clear')){selected=[];draw();}if(b.dataset.unlink){const r=store.dispatch('unlink',{key:b.dataset.unlink});feedback(r.message);}});
 shell.addEventListener('submit',e=>{e.preventDefault();if(e.target.hasAttribute('data-case-reconstruction')){const data=new FormData(e.target),answers=Object.fromEntries(CASE_FIELDS.map(f=>[f.name,data.get(f.name)]));store.dispatch('mark',{table:'case-reconstruction',rows:CASE_FIELDS.map(f=>answers[f.name])});const r=store.dispatch('reconstruct',answers);body.querySelector('[data-case-result]').textContent=r.message;}if(e.target.hasAttribute('data-pocket-synthesize')){const r=store.dispatch('synthesize',{pair:selected});body.querySelector('[data-synthesis-result]').textContent=r.message;}if(e.target.hasAttribute('data-pocket-link')){const r=store.dispatch('link',{from:selected[0],to:selected[1],relation:new FormData(e.target).get('relation')});body.querySelector('[data-pocket-result]').textContent=r.message;}if(e.target.hasAttribute('data-pocket-note')){draft=new FormData(e.target).get('personal');feedback(store.dispatch('note',{text:draft}).message);}});
 shell.addEventListener('change',e=>{if(CASE_FIELDS.some(f=>f.name===e.target.name)){const form=e.target.closest('form[data-case-reconstruction]');if(form)caseDraft=CASE_FIELDS.map(f=>form.elements[f.name].value);return;}if(e.target.dataset.card){const id=e.target.dataset.card,result=toggleClueSelection(selected,id,e.target.checked);if(result.message){e.target.checked=false;feedback(result.message);return;}selected=result.selected;draw();body.querySelector(`[data-card="${id}"]`)?.focus({preventScroll:true});return;}if(e.target.hasAttribute('data-pocket-sound'))store.dispatch('sound',{on:e.target.checked});});
 function highlight(message){notebookFeedback.notify({force:true});feedback(message);sound();}
 store.subscribe((_s,meta)=>{draw();if(meta.kind==='collect'){notebookFeedback.notify();feedback(meta.result.message);sound();}if(['discover','synthesize','reconstruct'].includes(meta.kind)||meta.kind==='vault'&&!hadVault)highlight(meta.result.message);hadVault=!!store.get().vault;if(!meta.available)feedback('当前浏览器存储不可用，跨页进度可能无法保存。');});draw();return {feedback,highlight,draw};
}
